by={n['id']:n for n in json.loads((R/'data/notes.json').read_text())};out=['# October 2026 · Original Mains answer frameworks','','Eight150/250-word planning frameworks;not previous-year questions or completeness/current-law certification. Source stages and disputed figures must be retained.','']
# Explicit prose formatting avoids changing stable references.
for i,(ref,prompt,pts)in enumerate(F,1):
 key=f'E17-2610-{ref:03}';out += [f'## {i}. {prompt}',f'Study anchor: {key} · {by[key]["title"]}','']+[f'{j}. {clean(x)}'for j,x in enumerate(pts,1)]+['']
